package com.lenid.accountlab;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;
/** Only executed explicitly on an emulator. Codes are supplied by the external test harness. */
public class LoginTest extends Instrumentation {
 PhoneActivity app;Bundle args;JSONObject report=new JSONObject();
 public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 boolean click(View v,String text){if(v instanceof Button&&((Button)v).getText().toString().equals(text)){v.performClick();return true;}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(click(((ViewGroup)v).getChildAt(i),text))return true;return false;}
 void button(String label)throws Exception{runOnMainSync(()->{if(!click(app.root,label))throw new IllegalStateException(label);});waitBusy();}
 void waitBusy()throws Exception{for(int i=0;i<180&&app.busy;i++)Thread.sleep(250);waitForIdleSync();if(app.busy)throw new Exception("Operation timeout");}
 public void onStart(){boolean ok=false;try{LabHttp.emulatorOnly();String phase=args.getString("phase","");if(phase.equals("setup")){JSONObject c=LabHttp.validate(args.getString("connection"));getTargetContext().getSharedPreferences("server",0).edit().putString("connection",c.toString()).commit();AccountGate.clear(getTargetContext());}
 app=(PhoneActivity)startActivitySync(new Intent(getTargetContext(),PhoneActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitBusy();
 if(phase.equals("setup")){runOnMainSync(()->app.email.setText("release-test@example.test"));button("Получить код");if(app.challenge.isEmpty())throw new Exception(app.notice);report.put("challenge_id",app.challenge);app.prefs.edit().putString("test_challenge",app.challenge).commit();}
 else if(phase.equals("login")){runOnMainSync(()->{app.challenge=app.prefs.getString("test_challenge","");app.draw();app.otp.setText(args.getString("code"));});button("Войти");if(!app.logged()||app.me==null)throw new Exception(app.notice);report.put("logged_in",true);}
 else if(phase.equals("profile")){runOnMainSync(()->app.name.setText("Проверка профиля"));button("Сохранить имя");if(!app.me.getJSONObject("profile").getString("display_name").equals("Проверка профиля"))throw new Exception(app.notice);report.put("name_saved",true);String before=app.prefs.getString("refresh","");app.prefs.edit().putString("access","invalid-test-access").commit();app.api("GET","/v1/me",null);if(before.equals(app.prefs.getString("refresh","")))throw new Exception("Refresh not rotated");report.put("automatic_refresh",true);}
 else if(phase.equals("pair")){runOnMainSync(()->app.onActivityResult(63,Activity.RESULT_OK,new Intent().putExtra("SCAN_RESULT",args.getString("qr"))));choose("ПРОДОЛЖИТЬ");Thread.sleep(500);waitBusy();if(app.pairingId.isEmpty())throw new Exception(app.notice);report.put("qr_result_claimed",true).put("confirmation_phrase",app.pairingPhrase);}
 else if(phase.equals("gallery")){if(!app.logged()||app.me==null)throw new Exception("Gallery requires login: "+app.notice);android.content.ContentValues c=new android.content.ContentValues();String filename="Avatar"+(System.currentTimeMillis()%100000)+".png";c.put(android.provider.MediaStore.Images.Media.DISPLAY_NAME,filename);c.put(android.provider.MediaStore.Images.Media.MIME_TYPE,"image/png");c.put(android.provider.MediaStore.Images.Media.RELATIVE_PATH,"Pictures/ProfileTests");c.put(android.provider.MediaStore.Images.Media.IS_PENDING,1);android.net.Uri uri=getTargetContext().getContentResolver().insert(android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI,c);try(InputStream in=getTargetContext().getAssets().open("gallery-avatar.png");OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}c.clear();c.put(android.provider.MediaStore.Images.Media.IS_PENDING,0);getTargetContext().getContentResolver().update(uri,c,null,null);int revision=app.me.getJSONObject("profile").getInt("revision");button("Выбрать фото");Thread.sleep(1200);getUiAutomation().performGlobalAction(1);Thread.sleep(1200);if(app.api("GET","/v1/me",null).getJSONObject("profile").getInt("revision")!=revision)throw new Exception("Cancel changed profile");button("Выбрать фото");Thread.sleep(1500);if(find(getUiAutomation().getRootInActiveWindow(),filename)==null){choose("Show roots");choose("Recent");}choose(filename.replace(".png",""));for(int i=0;i<90;i++){Thread.sleep(300);if(!app.busy&&app.me.getJSONObject("profile").getInt("revision")>revision)break;}if(app.me.getJSONObject("profile").getInt("revision")<=revision)throw new Exception("Photo not uploaded: "+app.notice);report.put("gallery_selected",true).put("cancel_preserved_profile",true).put("avatar_id",app.me.getJSONObject("profile").getString("avatar_object_id"));}
 else if(phase.equals("restore")){if(!app.logged()||app.me==null||!app.prefs.contains("photo_uri"))throw new Exception("Profile/photo not restored");report.put("restored",true).put("name",app.me.getJSONObject("profile").getString("display_name"));}
 else if(phase.equals("logout")){button("Выйти из аккаунта");if(AccountGate.logged()||app.prefs.contains("photo_uri"))throw new Exception("Logout incomplete");report.put("logged_out",true);}
 else throw new Exception("Unknown phase");ok=true;
 }catch(Exception e){try{report.put("error",e.toString());}catch(Exception ignored){}}try{report.put("status",ok?"PASS":"FAIL");try(FileWriter f=new FileWriter(new File(getTargetContext().getFilesDir(),"release-test.json"))){f.write(report.toString(2));}}catch(Exception ignored){}Bundle out=new Bundle();out.putString("stream",report.toString());finish(ok?-1:0,out);}
 android.view.accessibility.AccessibilityNodeInfo find(android.view.accessibility.AccessibilityNodeInfo n,String text){if(n==null)return null;if(n.getText()!=null&&n.getText().toString().contains(text)||n.getContentDescription()!=null&&n.getContentDescription().toString().contains(text))return n;for(int i=0;i<n.getChildCount();i++){android.view.accessibility.AccessibilityNodeInfo x=find(n.getChild(i),text);if(x!=null)return x;}return null;}
 String tree(android.view.accessibility.AccessibilityNodeInfo n){if(n==null)return "null";String out="["+n.getText()+"|"+n.getContentDescription()+"]";for(int i=0;i<n.getChildCount();i++)out+=tree(n.getChild(i));return out;}
 void choose(String text)throws Exception{for(int t=0;t<20;t++){android.view.accessibility.AccessibilityNodeInfo n=find(getUiAutomation().getRootInActiveWindow(),text);if(n!=null){android.graphics.Rect bounds=new android.graphics.Rect();n.getBoundsInScreen(bounds);if(n.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK))return;if(!bounds.isEmpty()){long now=android.os.SystemClock.uptimeMillis();android.view.MotionEvent down=android.view.MotionEvent.obtain(now,now,android.view.MotionEvent.ACTION_DOWN,bounds.centerX(),bounds.centerY(),0);android.view.MotionEvent up=android.view.MotionEvent.obtain(now,now+100,android.view.MotionEvent.ACTION_UP,bounds.centerX(),bounds.centerY(),0);down.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);up.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(down,true);getUiAutomation().injectInputEvent(up,true);down.recycle();up.recycle();return;}}Thread.sleep(400);}throw new Exception("Picker item missing: "+text+" tree="+tree(getUiAutomation().getRootInActiveWindow()));}
}
